  "implementation": "import math

def solve(case):
    if not isinstance(case, dict) or 'matrix' not in case:
        raise ValueError('Invalid case: must contain "matrix"')
    matrix = case['matrix']
    if not isinstance(matrix, list) or len(matrix) == 0:
        raise ValueError('Matrix must be a nonempty list')
    rows = len(matrix)
    cols = len(matrix[0])
    if cols == 0:
        raise ValueError('Matrix must have at least one column')
    for row in matrix:
        if not isinstance(row, list) or len(row) != cols:
            raise ValueError('All rows must have the same length')
    df = [0] * cols
    for row in matrix:
        for c, val in enumerate(row):
            if val != 0:
                df[c] += 1
    idf = []
    for d in df:
        if d < 0 or d > rows:
            raise ValueError('Invalid document frequency')
        idf_val = math.log(1 + rows / (1 + d))
        idf.append(round(idf_val, 6))
    weighted_matrix = []
    degrees = []
    for row in matrix:
        new_row = []
        row_sum = 0.0
        for c, val in enumerate(row):
            w = val * idf[c]
            w_rounded = round(w, 6)
            new_row.append(w_rounded)
            row_sum += w_rounded
        weighted_matrix.append(new_row)
        degrees.append(round(row_sum, 6))
    return {
        'idf': idf,
        'weighted_matrix': weighted_matrix,
        'degrees': degrees
    }"
}
